import unittest

import registry


class TestRegistry(unittest.TestCase):
    def test_a_starts_empty(self):
        self.assertEqual(registry.count(), 0)

    def test_b_adding_counts_one(self):
        registry.add('ada')
        self.assertEqual(registry.count(), 1)
